// Helper functions for device management
const toggleDevice = async (deviceId: string) => {
  const entityId = getEntityId(deviceId);
  const currentState = deviceStates[deviceId] || false;
  const newState = !currentState;

  // Update both deviceStates and devicePowerStates immediately for responsiveness
  setDeviceStates(prev => ({
    ...prev,
    [deviceId]: newState
  }));
  setDevicePowerStates(prev => ({
    ...prev,
    [deviceId]: newState
  }));

  try {
    // Determine the domain from entity ID
    const domain = entityId.split('.')[0];
    // Home Assistant API call to turn the device on or off
    const response = await fetch(`/api/services/${domain}/turn_${newState ? 'on' : 'off'}`, {
      method: 'POST',
      headers: {
        'Authorization': 'Bearer ' + TOKEN,
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        entity_id: entityId,
      }),
    });

    if (!response.ok) {
      throw new Error(`Failed to toggle the device: ${response.statusText}`);
    }
  } catch (error) {
    console.error('Error toggling device:', error);
    // Revert both states if the API call fails
    setDeviceStates(prev => ({
      ...prev,
      [deviceId]: currentState
    }));
    setDevicePowerStates(prev => ({
      ...prev,
      [deviceId]: currentState
    }));
  }
};

