     let hubCenter: { x: number; y: number } | null = null;
const hubImage = hub.querySelector('use, image') as SVGGraphicsElement | null;
if (hubImage && svg) {
  const bbox = hubImage.getBBox();
  const ctm = hubImage.getScreenCTM();
  if (ctm) {
    // Center in local coordinates
    const localCenter = svg.createSVGPoint();
    localCenter.x = bbox.x + bbox.width / 2;
    localCenter.y = bbox.y + bbox.height / 2;
    // Transform to screen coordinates
    const screenCenter = localCenter.matrixTransform(ctm);
    // Now, convert screen coordinates back to SVG coordinates
    const svgCTM = svg.getScreenCTM();
    if (svgCTM) {
      const svgCTMInverse = svgCTM.inverse();
      const svgCenter = svg.createSVGPoint();
      svgCenter.x = screenCenter.x;
      svgCenter.y = screenCenter.y;
      const transformed = svgCenter.matrixTransform(svgCTMInverse);
      hubCenter = { x: transformed.x, y: transformed.y };
    }
  }
}
if (!hubCenter) {
  // fallback to group
  const hubBBox = hub.getBBox();
  const hubCTM = hub.getCTM();
  hubCenter = {
    x: hubBBox.x + hubBBox.width / 2,
    y: hubBBox.y + hubBBox.height / 2
  };
  if (hubCTM && svg) {
    const point = svg.createSVGPoint();
    point.x = hubCenter.x;
    point.y = hubCenter.y;
    const transformed = point.matrixTransform(hubCTM);
    hubCenter = { x: transformed.x, y: transformed.y };
  }
}
