// Calculate dependency lines
useEffect(() => {
   if (!displayDependencies) {
     setDependencyLines([]);
     return;
   }
 
   const timeout = setTimeout(() => {
     const svg = document.getElementById("main-svg") as SVGSVGElement | null;
     if (!svg) return;
 
     const lines: Array<{
       x1: number; y1: number; x2: number; y2: number;
       fromDevice: string; toDevice: string; ruleLabel: string;
     }> = [];
 
     dependencyRules.forEach(rule => {
       rule.chain.forEach(({ from, to }) => {
         const fromDevice = document.getElementById(from) as SVGGraphicsElement | null;
         const toDevice = document.getElementById(to) as SVGGraphicsElement | null;
         if (!fromDevice || !toDevice) return;
 
         let fromCenter: { x: number; y: number } | null = null;
         let fromElement = fromDevice.querySelector('use, image') as SVGGraphicsElement | null;
         if (!fromElement) fromElement = fromDevice;
         if (fromElement && svg) {
           const bbox = fromElement.getBBox();
           const ctm = fromElement.getScreenCTM();
           if (ctm) {
             const localCenter = svg.createSVGPoint();
             localCenter.x = bbox.x + bbox.width / 2;
             localCenter.y = bbox.y + bbox.height / 2;
             const screenCenter = localCenter.matrixTransform(ctm);
             const svgCTM = svg.getScreenCTM();
             if (svgCTM) {
               const svgCTMInverse = svgCTM.inverse();
               const svgCenter = svg.createSVGPoint();
               svgCenter.x = screenCenter.x;
               svgCenter.y = screenCenter.y;
               const transformed = svgCenter.matrixTransform(svgCTMInverse);
               fromCenter = { x: transformed.x, y: transformed.y };
             }
           }
         }
 
         let toCenter: { x: number; y: number } | null = null;
         let toElement = toDevice.querySelector('use, image') as SVGGraphicsElement | null;
         if (!toElement) toElement = toDevice;
         if (toElement && svg) {
           const bbox = toElement.getBBox();
           const ctm = toElement.getScreenCTM();
           if (ctm) {
             const localCenter = svg.createSVGPoint();
             localCenter.x = bbox.x + bbox.width / 2;
             localCenter.y = bbox.y + bbox.height / 2;
             const screenCenter = localCenter.matrixTransform(ctm);
             const svgCTM = svg.getScreenCTM();
             if (svgCTM) {
               const svgCTMInverse = svgCTM.inverse();
               const svgCenter = svg.createSVGPoint();
               svgCenter.x = screenCenter.x;
               svgCenter.y = screenCenter.y;
               const transformed = svgCenter.matrixTransform(svgCTMInverse);
               toCenter = { x: transformed.x, y: transformed.y };
             }
           }
         }
 
         if (fromCenter && toCenter) {
           lines.push({
             x1: fromCenter.x,
             y1: fromCenter.y,
             x2: toCenter.x,
             y2: toCenter.y,
             fromDevice: from,
             toDevice: to,
             ruleLabel: rule.label
           });
         }
       });
     });
 
     setDependencyLines(lines);
   }, 100);
 
   return () => {
     clearTimeout(timeout);
     setDependencyLines([]);
   };
 }, [displayDependencies]);


